<template>
  <section class="manager"><header><div><h3>Preventive maintenance reminders</h3><p>Set the next service milestone by date or mileage and track customer follow-up.</p></div><button class="primary" @click="open = !open">{{ open ? 'Cancel' : 'Add reminder' }}</button></header>
    <form v-if="open" class="form" @submit.prevent="submit"><label>Vehicle / registration<input v-model.trim="form.vehicle" required /></label><label>Customer<input v-model.trim="form.customer" required /></label><label>Phone<input v-model.trim="form.phone" /></label><label>Service due<input v-model.trim="form.service" required placeholder="Oil and filter" /></label><label>Due date<input v-model="form.dueDate" type="date" /></label><label>Due mileage (km)<input v-model.number="form.dueKm" type="number" min="0" /></label><button class="primary">Save reminder</button></form>
    <div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Customer</th><th>Service due</th><th>Date</th><th>Odometer</th><th>Follow-up</th></tr></thead><tbody><tr v-for="r in reminders" :key="r.id"><td><strong>{{ r.vehicle }}</strong></td><td>{{ r.customer }}<small>{{ r.phone || 'No phone recorded' }}</small></td><td>{{ r.service }}</td><td>{{ r.dueDate || 'Not set' }}</td><td>{{ r.dueKm ? Number(r.dueKm).toLocaleString()+' km' : 'Not set' }}</td><td><select :value="r.status" @change="$emit('update-status',{id:r.id,status:$event.target.value})"><option>Due</option><option>Contacted</option><option>Booked</option><option>Completed</option></select></td></tr><tr v-if="!reminders.length"><td colspan="6" class="empty">No upcoming reminders have been recorded.</td></tr></tbody></table></div>
  </section>
</template>
<script setup>
import { reactive, ref } from 'vue'
defineProps({reminders:{type:Array,default:()=>[]}});const emit=defineEmits(['create','update-status']);const open=ref(false)
const form=reactive({vehicle:'',customer:'',phone:'',service:'',dueDate:'',dueKm:0})
function submit(){emit('create',{...form,id:crypto.randomUUID(),status:'Due'});Object.assign(form,{vehicle:'',customer:'',phone:'',service:'',dueDate:'',dueKm:0});open.value=false}
</script>
<style scoped>
.manager{display:grid;gap:14px}header{display:flex;justify-content:space-between;align-items:center}h3{margin:0;font-size:18px}header p{margin:5px 0 0;color:#6c7482;font-size:12px}.primary{padding:9px 12px;border:0;border-radius:7px;background:#355fa0;color:white;font-weight:700;cursor:pointer}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:15px;background:#f4f6f9;border-radius:9px}.form label{display:grid;gap:5px;color:#586376;font-size:11px;font-weight:700}.form input{padding:9px;border:1px solid #d5dbe4;border-radius:6px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px}th,td{padding:10px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#758093;font-size:9px;text-transform:uppercase}td small{display:block;color:#7a8596;font-size:10px;margin-top:3px}td select{padding:6px;border:1px solid #d5dbe4;border-radius:5px;background:white}.empty{text-align:center;padding:24px;color:#8791a0}@media(max-width:650px){.form{grid-template-columns:repeat(2,1fr)}}@media(max-width:450px){.form{grid-template-columns:1fr}}
</style>
